-- Ledger-integrity: exclude voided/cancelled payments from the Power BI payment views.
-- Generated 2026-09-17 from the live definitions on the prod copy; each view is
-- recreated unchanged except for one added predicate on the payment status. A voided payment
-- (auditor soft-delete rule) has its ledger entries reversed and must not count as spent,
-- collected, outstanding or late. Unpaid drafts stay (they are reported as commitments).
-- Apply BEFORE deploying the void feature. Idempotent (CREATE OR REPLACE).
-- Not touched (already filter on a positive status): fact_project_expenses, fact_project_directpayments,
-- fact_nonproject_commitments, fact_apartment_* rows keyed on = 'PMNT_RECEIVED'.

-- payments: added WHERE
CREATE OR REPLACE VIEW Payments AS SELECT p.PAYMENT_ID AS PaymentId,p.AMOUNT AS Amount,p.ACTUAL_CURRENCY_AMOUNT AS ActualAmount,COALESCE(p.CURRENCY_UOM_ID,'EGP') AS CurrencyUomId,p.PARTY_ID_FROM AS PartyIdFrom,pf.DESCRIPTION AS PartyNameFrom,p.PARTY_ID_TO AS PartyIdTo,COALESCE(pt.DESCRIPTION,(CASE WHEN (p.PARTY_ID_TO = 'Company') THEN 'Company' ELSE p.PARTY_ID_TO END),'Unknown') AS PartyNameTo,p.PAYMENT_TYPE_ID AS PaymentTypeId,p.SALES_REQUEST_ID AS SalesRequestId,pt_type.DESCRIPTION AS PaymentTypeDescription,pt_type.DESCRIPTION_ARABIC AS PaymentTypeDescriptionArabic,p.PAYMENT_METHOD_TYPE_ID AS PaymentMethodTypeId,pmt_type.DESCRIPTION AS PaymentMethodTypeName,pmt_type.DESCRIPTION_ARABIC AS PaymentMethodTypeNameArabic,p.PAYMENT_REF_NUM AS PaymentRefNum,p.PAYMENT_METHOD_ID AS PaymentMethodId,pm.DESCRIPTION AS PaymentMethodName,prod.PRODUCT_ID AS ProductId,prod.BUILDING_NUMBER AS BuildingNumber,p.WORK_EFFORT_ID AS ProjectId,we.PROJECT_NAME AS ProjectName,p.COST_CENTER_ID AS CostCenterId,cc.DESCRIPTION AS CostCenterName,opp.ORDER_ID AS OrderId,p.STATUS_ID AS StatusId,si.DESCRIPTION AS StatusNameEnglish,si.DESCRIPTION_ARABIC AS StatusNameArabic,p.EFFECTIVE_DATE AS EffectiveDate,(TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) AS DaysUntilDue,(CASE WHEN ((p.STATUS_ID = 'PMNT_RECEIVED') OR (p.STATUS_ID <> 'PMNT_NOT_PAID')) THEN 'Received' WHEN (p.EFFECTIVE_DATE >= CURDATE()) THEN 'Upcoming' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(p.EFFECTIVE_DATE)) BETWEEN 1 AND 30) THEN 'Late (1-30 Days)' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(p.EFFECTIVE_DATE)) BETWEEN 31 AND 90) THEN 'Late (31-90 Days)' ELSE 'Late (Over 90 Days)' END) AS OverdueBucket,(CASE WHEN (p.STATUS_ID <> 'PMNT_NOT_PAID') THEN si.DESCRIPTION_ARABIC ELSE (CASE WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) < 0) THEN (CASE WHEN (ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) <= 30) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة' ELSE 'مستحق' END),' متأخرة منذ ',ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))),' يوم') ELSE CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة' ELSE 'مستحق' END),' متأخرة جداً ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 0) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' اليوم') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 1) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' غداً') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 3) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' بعد ',(TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())),' أيام') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 7) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' هذا الأسبوع') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 30) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' خلال الشهر') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 90) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' خلال 3 أشهر ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') ELSE CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' لاحقاً ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) END) AS DueStatusArabic,(CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 1 ELSE 0 END) AS IsDisbursement,(CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN p.PARTY_ID_FROM ELSE p.PARTY_ID_TO END) AS OrganizationPartyId,(CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'Outbound' WHEN (p.PARTY_ID_TO = 'Company') THEN 'Inbound' ELSE 'Unknown' END) AS PaymentDirection,p.COMMENTS AS Comments,p.CHEQUENUMBER AS ChequeNumber,p.CHEQUEDATE AS ChequeDate,p.OVERRIDE_GL_ACCOUNT_ID AS OverrideGlAccountId,p.CREATED_STAMP AS CreatedDate,p.PAYMENT_PREFERENCE_ID AS PaymentPreferenceId FROM ((((((((((((PAYMENT p LEFT JOIN PARTY pf ON((p.PARTY_ID_FROM = pf.PARTY_ID))) LEFT JOIN PARTY pt ON((p.PARTY_ID_TO = pt.PARTY_ID))) LEFT JOIN PAYMENT_METHOD pm ON((p.PAYMENT_METHOD_ID = pm.PAYMENT_METHOD_ID))) LEFT JOIN COST_CENTER cc ON((p.COST_CENTER_ID = cc.COST_CENTER_ID))) LEFT JOIN STATUS_ITEM si ON((p.STATUS_ID = si.STATUS_ID))) LEFT JOIN WORK_EFFORT we ON((p.WORK_EFFORT_ID = we.WORK_EFFORT_ID))) LEFT JOIN PAYMENT_TYPE pt_type ON((p.PAYMENT_TYPE_ID = pt_type.PAYMENT_TYPE_ID))) LEFT JOIN PAYMENT_METHOD_TYPE pmt_type ON((p.PAYMENT_METHOD_TYPE_ID = pmt_type.PAYMENT_METHOD_TYPE_ID))) LEFT JOIN ORDER_PAYMENT_PREFERENCE opp ON((p.PAYMENT_PREFERENCE_ID = opp.ORDER_PAYMENT_PREFERENCE_ID))) LEFT JOIN ORDER_HEADER ord ON((opp.ORDER_ID = ord.ORDER_ID))) LEFT JOIN SALES_REQUEST sr ON((p.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) LEFT JOIN PRODUCT prod ON((sr.PRODUCT_ID = prod.PRODUCT_ID))) WHERE (p.STATUS_ID IS NULL OR p.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) ORDER BY p.EFFECTIVE_DATE DESC,p.PAYMENT_ID DESC;

-- payments_2: added WHERE
CREATE OR REPLACE VIEW Payments_2 AS SELECT p.PAYMENT_ID AS PaymentId,p.AMOUNT AS Amount,p.ACTUAL_CURRENCY_AMOUNT AS ActualAmount,COALESCE(p.CURRENCY_UOM_ID,'EGP') AS CurrencyUomId,p.PARTY_ID_FROM AS PartyIdFrom,pf.DESCRIPTION AS PartyNameFrom,p.PARTY_ID_TO AS PartyIdTo,COALESCE(pt.DESCRIPTION,(CASE WHEN (p.PARTY_ID_TO = 'Company') THEN 'Company' ELSE p.PARTY_ID_TO END),'Unknown') AS PartyNameTo,p.PAYMENT_TYPE_ID AS PaymentTypeId,pt_type.DESCRIPTION AS PaymentTypeDescription,pt_type.DESCRIPTION_ARABIC AS PaymentTypeDescriptionArabic,p.PAYMENT_METHOD_TYPE_ID AS PaymentMethodTypeId,pmt_type.DESCRIPTION_ARABIC AS PaymentMethodTypeNameArabic,p.PAYMENT_REF_NUM AS PaymentRefNum,p.PAYMENT_METHOD_ID AS PaymentMethodId,pm.DESCRIPTION AS PaymentMethodName,prod.PRODUCT_ID AS ProductId,prod.BUILDING_NUMBER AS BuildingNumber,p.WORK_EFFORT_ID AS ProjectId,we.PROJECT_NAME AS ProjectName,p.COST_CENTER_ID AS CostCenterId,cc.DESCRIPTION AS CostCenterName,opp.ORDER_ID AS OrderId,p.STATUS_ID AS StatusId,si.DESCRIPTION_ARABIC AS StatusNameArabic,p.EFFECTIVE_DATE AS EffectiveDate,YEAR(p.EFFECTIVE_DATE) AS DueYear,CONCAT('الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE)) AS DueQuarterArabic,CONCAT(YEAR(p.EFFECTIVE_DATE),LPAD(CEILING((MONTH(p.EFFECTIVE_DATE) / 3)),2,'0')) AS DueQuarterSort,(TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) AS DaysUntilDue,(CASE WHEN (p.STATUS_ID <> 'PMNT_NOT_PAID') THEN si.DESCRIPTION_ARABIC ELSE (CASE WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) < 0) THEN (CASE WHEN (ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) <= 30) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة' ELSE 'مستحق' END),' متأخرة منذ ',ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))),' يوم') ELSE CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة' ELSE 'مستحق' END),' متأخرة جداً ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 0) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' اليوم') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 1) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' غداً') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 3) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' بعد ',(TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())),' أيام') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 7) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' هذا الأسبوع') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 30) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' خلال الشهر') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 90) THEN CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' خلال 3 أشهر ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') ELSE CONCAT((CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'دفعة مستحقة' ELSE 'مستحق' END),' لاحقاً ','(الربع ',(CASE WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 1 AND 3) THEN 'الأول' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 4 AND 6) THEN 'الثاني' WHEN (MONTH(p.EFFECTIVE_DATE) BETWEEN 7 AND 9) THEN 'الثالث' ELSE 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) END) AS DueStatusArabic,(CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 1 ELSE 0 END) AS IsDisbursement,(CASE WHEN (pt_type.PARENT_TYPE_ID = 'DISBURSEMENT') THEN 'Outbound' WHEN (p.PARTY_ID_TO = 'Company') THEN 'Inbound' ELSE 'Unknown' END) AS PaymentDirection,p.COMMENTS AS Comments,p.CHEQUENUMBER AS ChequeNumber,p.CREATED_STAMP AS CreatedDate FROM (((((((((((PAYMENT p LEFT JOIN PARTY pf ON((p.PARTY_ID_FROM = pf.PARTY_ID))) LEFT JOIN PARTY pt ON((p.PARTY_ID_TO = pt.PARTY_ID))) LEFT JOIN PAYMENT_METHOD pm ON((p.PAYMENT_METHOD_ID = pm.PAYMENT_METHOD_ID))) LEFT JOIN COST_CENTER cc ON((p.COST_CENTER_ID = cc.COST_CENTER_ID))) LEFT JOIN STATUS_ITEM si ON((p.STATUS_ID = si.STATUS_ID))) LEFT JOIN WORK_EFFORT we ON((p.WORK_EFFORT_ID = we.WORK_EFFORT_ID))) LEFT JOIN PAYMENT_TYPE pt_type ON((p.PAYMENT_TYPE_ID = pt_type.PAYMENT_TYPE_ID))) LEFT JOIN PAYMENT_METHOD_TYPE pmt_type ON((p.PAYMENT_METHOD_TYPE_ID = pmt_type.PAYMENT_METHOD_TYPE_ID))) LEFT JOIN ORDER_PAYMENT_PREFERENCE opp ON((p.PAYMENT_PREFERENCE_ID = opp.ORDER_PAYMENT_PREFERENCE_ID))) LEFT JOIN SALES_REQUEST sr ON((p.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) LEFT JOIN PRODUCT prod ON((sr.PRODUCT_ID = prod.PRODUCT_ID))) WHERE (p.STATUS_ID IS NULL OR p.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) ORDER BY p.EFFECTIVE_DATE DESC,p.PAYMENT_ID DESC;

-- fact_project_directpayments_2: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Project_DirectPayments_2 AS SELECT pyt.PAYMENT_ID AS PaymentId,pyt.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,ptt.DESCRIPTION_ARABIC AS PaymentTypeDescription,pyt.PAYMENT_METHOD_ID AS PaymentMethodId,pyt.PAYMENT_METHOD_TYPE_ID AS PAYMENT_METHOD_TYPE_ID,pmt.DESCRIPTION_ARABIC AS PaymentMethodTypeDescription,pyt.PARTY_ID_FROM AS PartyIdFrom,pty_from.DESCRIPTION AS PartyIdFromName,pyt.PARTY_ID_TO AS PartyIdTo,COALESCE(pty_to.DESCRIPTION,(CASE WHEN (pyt.PARTY_ID_TO = 'Company') THEN 'Golden Land' ELSE pyt.PARTY_ID_TO END)) AS PartyIdToName,pyt.STATUS_ID AS STATUS_ID,sts.DESCRIPTION_ARABIC AS StatusDescription,sts.DESCRIPTION AS StatusDescriptionEnglish,pyt.EFFECTIVE_DATE AS EFFECTIVE_DATE,pyt.CREATED_STAMP AS CreatedStamp,pyt.COMMENTS AS COMMENTS,pyt.PAYMENT_REF_NUM AS PaymentRefNum,pyt.PAYMENT_PREFERENCE_ID AS PaymentPreferenceId,pyt.IS_BANK_TRANSFER AS IsBankTransfer,pyt.AMOUNT AS AMOUNT,COALESCE(pyt.ACTUAL_CURRENCY_AMOUNT,pyt.AMOUNT) AS ActualCurrencyAmount,COALESCE(pyt.CURRENCY_UOM_ID,'EGP') AS CurrencyUomId,TRUE AS IsDisbursement,NULL AS OrganizationPartyId,dp.ProjectId AS ProjectId,dp.ProjectName AS ProjectName,pyt.OVERRIDE_GL_ACCOUNT_ID AS OverrideGlAccountId,pyt.COST_CENTER_ID AS CostCenterId,cc.DESCRIPTION AS CostCenterDescription,sr.SALES_REQUEST_ID AS SALES_REQUEST_ID,prod.PRODUCT_ID AS PRODUCT_ID,prod.BUILDING_NUMBER AS BUILDING_NUMBER,pyt.APPROVED_BY_PARTY_ID AS ApprovedByPartyId,approved.DESCRIPTION AS ApprovedByPartyName,pyt.CREATED_BY_PARTY_ID AS CreatedByPartyId,created_by.DESCRIPTION AS CreatedByPartyName,pyt.CHEQUENUMBER AS ChequeNumber,pyt.CHEQUEDATE AS ChequeDate,(CASE WHEN ((pyt.STATUS_ID <> 'PMNT_NOT_PAID') AND (pyt.STATUS_ID IS NOT NULL)) THEN COALESCE(sts.DESCRIPTION_ARABIC,pyt.STATUS_ID) WHEN (pyt.EFFECTIVE_DATE IS NULL) THEN 'غير محدد' ELSE (CASE WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) < 0) THEN (CASE WHEN (ABS((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) = 1) THEN 'دفعة مستحقة متأخرة بيوم واحد' WHEN (ABS((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) = 2) THEN 'دفعة مستحقة متأخرة بيومين' WHEN (ABS((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) <= 30) THEN CONCAT('دفعة مستحقة متأخرة منذ ',ABS((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))),' يوم') ELSE CONCAT('دفعة مستحقة متأخرة جداً (الربع ',(CASE (((MONTH(pyt.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(pyt.EFFECTIVE_DATE),')') END) WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 0) THEN 'دفعة مستحقة اليوم' WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 1) THEN 'دفعة مستحقة غداً' WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 3) THEN CONCAT('دفعة مستحقة بعد ',(TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())),' أيام') WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 7) THEN 'دفعة مستحقة هذا الأسبوع' WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 30) THEN 'دفعة مستحقة خلال الشهر' WHEN ((TO_DAYS(pyt.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 90) THEN CONCAT('دفعة مستحقة خلال 3 أشهر (الربع ',(CASE (((MONTH(pyt.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(pyt.EFFECTIVE_DATE),')') ELSE CONCAT('دفعة مستحقة لاحقاً (الربع ',(CASE (((MONTH(pyt.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(pyt.EFFECTIVE_DATE),')') END) END) AS DueStatusArabic FROM (((((((((((PAYMENT pyt JOIN PAYMENT_TYPE ptt ON((pyt.PAYMENT_TYPE_ID = ptt.PAYMENT_TYPE_ID))) JOIN STATUS_ITEM sts ON((pyt.STATUS_ID = sts.STATUS_ID))) JOIN PARTY pty_from ON((pyt.PARTY_ID_FROM = pty_from.PARTY_ID))) LEFT JOIN PAYMENT_METHOD_TYPE pmt ON((pyt.PAYMENT_METHOD_TYPE_ID = pmt.PAYMENT_METHOD_TYPE_ID))) LEFT JOIN PARTY pty_to ON((pyt.PARTY_ID_TO = pty_to.PARTY_ID))) LEFT JOIN COST_CENTER cc ON((pyt.COST_CENTER_ID = cc.COST_CENTER_ID))) LEFT JOIN SALES_REQUEST sr ON((pyt.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) LEFT JOIN PRODUCT prod ON((sr.PRODUCT_ID = prod.PRODUCT_ID))) LEFT JOIN PARTY approved ON((pyt.APPROVED_BY_PARTY_ID = approved.PARTY_ID))) LEFT JOIN PARTY created_by ON((pyt.CREATED_BY_PARTY_ID = created_by.PARTY_ID))) JOIN DimProject dp ON((pyt.OVERRIDE_GL_ACCOUNT_ID = dp.GlAccountId))) WHERE (pyt.STATUS_ID IS NULL OR pyt.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND ((((ptt.PARENT_TYPE_ID = 'DISBURSEMENT') OR (ptt.PAYMENT_TYPE_ID = 'DISBURSEMENT')) AND (dp.GlAccountType = 'PROJECT_MAIN') AND (pyt.OVERRIDE_GL_ACCOUNT_ID IS NOT NULL) AND (pyt.PAYMENT_TYPE_ID <> 'PAYROL_PAYMENT') AND EXISTS(SELECT 1 FROM Fact_Project_Expenses fpe WHERE (fpe.PaymentId = pyt.PAYMENT_ID)) IS FALSE));

-- fact_project_revenues: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Project_Revenues AS SELECT p.PAYMENT_ID AS PaymentId,p.SALES_REQUEST_ID AS SalesRequestId,sr.PRODUCT_ID AS ApartmentId,apt.BUILDING_NUMBER AS BuildingNumber,COALESCE(apt.PROJECT_ID,p.WORK_EFFORT_ID) AS ProjectId,proj.PROJECT_NAME AS ProjectName,p.PARTY_ID_FROM AS CustomerPartyId,pf.DESCRIPTION AS CustomerName,p.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,pt_type.DESCRIPTION_ARABIC AS PaymentTypeArabic,(CASE p.PAYMENT_TYPE_ID WHEN 'RECEIPT_ADVANCE_PAYMENT' THEN 'Advance Payment' WHEN 'RECEIPT_DUE_INSTALLMENT' THEN 'Installment' WHEN 'RECEIPT_MAINTENANCE_AMOUNT' THEN 'Maintenance Deposit' ELSE 'Other' END) AS RevenueCategory,COALESCE(p.AMOUNT,0) AS ScheduledAmount,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS CollectedAmount,(CASE WHEN (p.STATUS_ID <> 'PMNT_RECEIVED') THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS OutstandingAmount,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (p.EFFECTIVE_DATE < CURDATE())) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS LateAmount,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (p.EFFECTIVE_DATE > CURDATE())) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS FutureAmount,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (p.EFFECTIVE_DATE = CURDATE())) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS DueTodayAmount,(CASE WHEN (p.EFFECTIVE_DATE <= CURDATE()) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS ShouldHaveCollected,p.STATUS_ID AS StatusId,COALESCE(sts.DESCRIPTION_ARABIC,p.STATUS_ID) AS StatusDescription,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN 'Received' WHEN (p.EFFECTIVE_DATE < CURDATE()) THEN 'Late' ELSE 'Upcoming' END) AS PaymentStatus,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN 'Received' WHEN (p.EFFECTIVE_DATE >= CURDATE()) THEN 'Upcoming' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(p.EFFECTIVE_DATE)) BETWEEN 1 AND 30) THEN 'Late (1-30 Days)' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(p.EFFECTIVE_DATE)) BETWEEN 31 AND 90) THEN 'Late (31-90 Days)' ELSE 'Late (Over 90 Days)' END) AS OverdueBucket,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (p.EFFECTIVE_DATE < CURDATE())) THEN (TO_DAYS(CURDATE()) - TO_DAYS(p.EFFECTIVE_DATE)) ELSE 0 END) AS DaysOverdue,p.EFFECTIVE_DATE AS DueDate,p.CREATED_STAMP AS CreatedDate,p.COMMENTS AS COMMENTS,p.CHEQUENUMBER AS CHEQUENUMBER,(CASE WHEN ((p.STATUS_ID <> 'PMNT_NOT_PAID') AND (p.STATUS_ID IS NOT NULL)) THEN COALESCE(sts.DESCRIPTION_ARABIC,p.STATUS_ID) WHEN (p.EFFECTIVE_DATE IS NULL) THEN 'غير محدد' ELSE (CASE WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) < 0) THEN (CASE WHEN (ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) = 1) THEN 'مستحق متأخر بيوم واحد' WHEN (ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) = 2) THEN 'مستحق متأخر بيومين' WHEN (ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))) <= 30) THEN CONCAT('مستحق متأخر منذ ',ABS((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE()))),' يوم') ELSE CONCAT('مستحق متأخر جداً (الربع ',(CASE (((MONTH(p.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 0) THEN 'مستحق اليوم' WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) = 1) THEN 'مستحق غداً' WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 3) THEN CONCAT('مستحق بعد ',(TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())),' أيام') WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 7) THEN 'مستحق هذا الأسبوع' WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 30) THEN 'مستحق خلال الشهر' WHEN ((TO_DAYS(p.EFFECTIVE_DATE) - TO_DAYS(CURDATE())) <= 90) THEN CONCAT('مستحق خلال 3 أشهر (الربع ',(CASE (((MONTH(p.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') ELSE CONCAT('مستحق لاحقاً (الربع ',(CASE (((MONTH(p.EFFECTIVE_DATE) - 1) DIV 3) + 1) WHEN 1 THEN 'الأول' WHEN 2 THEN 'الثاني' WHEN 3 THEN 'الثالث' WHEN 4 THEN 'الرابع' END),' ',YEAR(p.EFFECTIVE_DATE),')') END) END) AS DueStatusArabic FROM ((((((PAYMENT p LEFT JOIN PARTY pf ON((p.PARTY_ID_FROM = pf.PARTY_ID))) LEFT JOIN PAYMENT_TYPE pt_type ON((p.PAYMENT_TYPE_ID = pt_type.PAYMENT_TYPE_ID))) LEFT JOIN STATUS_ITEM sts ON((p.STATUS_ID = sts.STATUS_ID))) LEFT JOIN SALES_REQUEST sr ON((p.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) LEFT JOIN PRODUCT apt ON((sr.PRODUCT_ID = apt.PRODUCT_ID))) LEFT JOIN WORK_EFFORT proj ON((COALESCE(apt.PROJECT_ID,p.WORK_EFFORT_ID) = proj.WORK_EFFORT_ID))) WHERE (p.STATUS_ID IS NULL OR p.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND (((p.PARTY_ID_TO = 'Company') AND (p.SALES_REQUEST_ID IS NOT NULL) AND (p.PAYMENT_TYPE_ID IN ('RECEIPT_ADVANCE_PAYMENT','RECEIPT_DUE_INSTALLMENT','RECEIPT_MAINTENANCE_AMOUNT')) AND (COALESCE(p.AMOUNT,0) > 0)));

-- fact_project_operatingexpenses: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Project_OperatingExpenses AS WITH RECURSIVE OperatingGlAccounts AS (SELECT w.WORK_EFFORT_ID AS ProjectId,w.OPERATING_EXPENSE_GL_ACCOUNT_ID AS GlAccountId FROM WORK_EFFORT w WHERE (w.OPERATING_EXPENSE_GL_ACCOUNT_ID IS NOT NULL) UNION ALL SELECT parent.ProjectId AS ProjectId,g.GL_ACCOUNT_ID AS GL_ACCOUNT_ID FROM (GL_ACCOUNT g JOIN OperatingGlAccounts parent ON((g.PARENT_GL_ACCOUNT_ID = parent.GlAccountId)))) SELECT pyt.PAYMENT_ID AS PaymentId,pyt.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,ptt.DESCRIPTION_ARABIC AS PaymentTypeDescription,pyt.PAYMENT_METHOD_ID AS PaymentMethodId,pyt.PAYMENT_METHOD_TYPE_ID AS PAYMENT_METHOD_TYPE_ID,pmt.DESCRIPTION_ARABIC AS PaymentMethodTypeDescription,pyt.PARTY_ID_FROM AS PartyIdFrom,COALESCE(pty_from.DESCRIPTION,'') AS PartyIdFromName,pyt.PARTY_ID_TO AS PartyIdTo,COALESCE(pty_to.DESCRIPTION,(CASE WHEN (pyt.PARTY_ID_TO = 'Company') THEN 'Golden Land' ELSE pyt.PARTY_ID_TO END)) AS PartyIdToName,pyt.STATUS_ID AS STATUS_ID,COALESCE(sts.DESCRIPTION_ARABIC,pyt.STATUS_ID) AS StatusDescription,COALESCE(sts.DESCRIPTION,pyt.STATUS_ID) AS StatusDescriptionEnglish,pyt.EFFECTIVE_DATE AS EFFECTIVE_DATE,pyt.CREATED_STAMP AS CreatedStamp,pyt.COMMENTS AS COMMENTS,pyt.PAYMENT_REF_NUM AS PaymentRefNum,pyt.PAYMENT_PREFERENCE_ID AS PaymentPreferenceId,pyt.IS_BANK_TRANSFER AS IsBankTransfer,pyt.AMOUNT AS AMOUNT,COALESCE(pyt.ACTUAL_CURRENCY_AMOUNT,pyt.AMOUNT) AS ActualCurrencyAmount,COALESCE(pyt.CURRENCY_UOM_ID,'EGP') AS CurrencyUomId,TRUE AS IsDisbursement,TRUE AS IsOperatingExpense,pyt.PARTY_ID_FROM AS OrganizationPartyId,pyt.WORK_EFFORT_ID AS ProjectId,pyt.OVERRIDE_GL_ACCOUNT_ID AS OverrideGlAccountId,pyt.COST_CENTER_ID AS CostCenterId,cc.DESCRIPTION AS CostCenterDescription,pyt.CHEQUENUMBER AS ChequeNumber,pyt.CHEQUEDATE AS ChequeDate FROM (((((((PAYMENT pyt JOIN PAYMENT_TYPE ptt ON((pyt.PAYMENT_TYPE_ID = ptt.PAYMENT_TYPE_ID))) LEFT JOIN STATUS_ITEM sts ON((pyt.STATUS_ID = sts.STATUS_ID))) LEFT JOIN PARTY pty_from ON((pyt.PARTY_ID_FROM = pty_from.PARTY_ID))) LEFT JOIN PAYMENT_METHOD_TYPE pmt ON((pyt.PAYMENT_METHOD_TYPE_ID = pmt.PAYMENT_METHOD_TYPE_ID))) LEFT JOIN PARTY pty_to ON((pyt.PARTY_ID_TO = pty_to.PARTY_ID))) LEFT JOIN COST_CENTER cc ON((pyt.COST_CENTER_ID = cc.COST_CENTER_ID))) JOIN OperatingGlAccounts ogl ON(((pyt.WORK_EFFORT_ID = ogl.ProjectId) AND (pyt.OVERRIDE_GL_ACCOUNT_ID = ogl.GlAccountId)))) WHERE (pyt.STATUS_ID IS NULL OR pyt.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND ((((ptt.PARENT_TYPE_ID = 'DISBURSEMENT') OR (ptt.PAYMENT_TYPE_ID = 'DISBURSEMENT')) AND (pyt.OVERRIDE_GL_ACCOUNT_ID IS NOT NULL)));

-- fact_project_operatingexpenses_2: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Project_OperatingExpenses_2 AS SELECT pyt.PAYMENT_ID AS PaymentId,pyt.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,ptt.DESCRIPTION_ARABIC AS PaymentTypeDescription,pyt.PAYMENT_METHOD_ID AS PaymentMethodId,pyt.PAYMENT_METHOD_TYPE_ID AS PAYMENT_METHOD_TYPE_ID,pmt.DESCRIPTION_ARABIC AS PaymentMethodTypeDescription,pyt.PARTY_ID_FROM AS PartyIdFrom,COALESCE(pty_from.DESCRIPTION,'') AS PartyIdFromName,pyt.PARTY_ID_TO AS PartyIdTo,COALESCE(pty_to.DESCRIPTION,(CASE WHEN (pyt.PARTY_ID_TO = 'Company') THEN 'Golden Land' ELSE pyt.PARTY_ID_TO END)) AS PartyIdToName,pyt.STATUS_ID AS STATUS_ID,COALESCE(sts.DESCRIPTION_ARABIC,pyt.STATUS_ID) AS StatusDescription,COALESCE(sts.DESCRIPTION,pyt.STATUS_ID) AS StatusDescriptionEnglish,pyt.EFFECTIVE_DATE AS EFFECTIVE_DATE,pyt.CREATED_STAMP AS CreatedStamp,pyt.COMMENTS AS COMMENTS,pyt.PAYMENT_REF_NUM AS PaymentRefNum,pyt.PAYMENT_PREFERENCE_ID AS PaymentPreferenceId,pyt.IS_BANK_TRANSFER AS IsBankTransfer,pyt.AMOUNT AS AMOUNT,COALESCE(pyt.ACTUAL_CURRENCY_AMOUNT,pyt.AMOUNT) AS ActualCurrencyAmount,COALESCE(pyt.CURRENCY_UOM_ID,'EGP') AS CurrencyUomId,TRUE AS IsDisbursement,TRUE AS IsOperatingExpense,pyt.PARTY_ID_FROM AS OrganizationPartyId,dp.ProjectId AS ProjectId,dp.ProjectName AS ProjectName,pyt.OVERRIDE_GL_ACCOUNT_ID AS OverrideGlAccountId,pyt.COST_CENTER_ID AS CostCenterId,cc.DESCRIPTION AS CostCenterDescription,pyt.CHEQUENUMBER AS ChequeNumber,pyt.CHEQUEDATE AS ChequeDate FROM (((((((PAYMENT pyt JOIN PAYMENT_TYPE ptt ON((pyt.PAYMENT_TYPE_ID = ptt.PAYMENT_TYPE_ID))) LEFT JOIN STATUS_ITEM sts ON((pyt.STATUS_ID = sts.STATUS_ID))) LEFT JOIN PARTY pty_from ON((pyt.PARTY_ID_FROM = pty_from.PARTY_ID))) LEFT JOIN PAYMENT_METHOD_TYPE pmt ON((pyt.PAYMENT_METHOD_TYPE_ID = pmt.PAYMENT_METHOD_TYPE_ID))) LEFT JOIN PARTY pty_to ON((pyt.PARTY_ID_TO = pty_to.PARTY_ID))) LEFT JOIN COST_CENTER cc ON((pyt.COST_CENTER_ID = cc.COST_CENTER_ID))) JOIN DimProject dp ON((pyt.OVERRIDE_GL_ACCOUNT_ID = dp.GlAccountId))) WHERE (pyt.STATUS_ID IS NULL OR pyt.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND ((((ptt.PARENT_TYPE_ID = 'DISBURSEMENT') OR (ptt.PAYMENT_TYPE_ID = 'DISBURSEMENT')) AND (dp.GlAccountType <> 'PROJECT_MAIN') AND (pyt.OVERRIDE_GL_ACCOUNT_ID IS NOT NULL) AND (pyt.PAYMENT_TYPE_ID <> 'PAYROL_PAYMENT') AND EXISTS(SELECT 1 FROM Fact_Project_Expenses fpe WHERE (fpe.PaymentId = pyt.PAYMENT_ID)) IS FALSE AND EXISTS(SELECT 1 FROM Fact_Project_DirectPayments_2 fdp WHERE (fdp.PaymentId = pyt.PAYMENT_ID)) IS FALSE));

-- fact_apartment_payments: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Apartment_Payments AS SELECT p.PAYMENT_ID AS PaymentId,p.SALES_REQUEST_ID AS SalesRequestId,sr.PRODUCT_ID AS ApartmentId,apt.PROJECT_ID AS ProjectId,proj.ProjectName AS ProjectName,p.PARTY_ID_FROM AS CustomerPartyId,pf.DESCRIPTION AS CustomerName,p.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,pt_type.DESCRIPTION_ARABIC AS PaymentTypeArabic,(CASE p.PAYMENT_TYPE_ID WHEN 'RECEIPT_ADVANCE_PAYMENT' THEN 'Advance Payment' WHEN 'RECEIPT_DUE_INSTALLMENT' THEN 'Installment' WHEN 'RECEIPT_MAINTENANCE_AMOUNT' THEN 'Maintenance Deposit' ELSE 'Other' END) AS RevenueCategory,COALESCE(p.AMOUNT,0) AS ScheduledAmount,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS CollectedAmount,(CASE WHEN (p.STATUS_ID <> 'PMNT_RECEIVED') THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS OutstandingAmount,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (CAST(p.EFFECTIVE_DATE AS DATE) < CURDATE())) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS LateAmount,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (CAST(p.EFFECTIVE_DATE AS DATE) >= CURDATE())) THEN COALESCE(p.AMOUNT,0) ELSE 0 END) AS FutureAmount,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN 'Received' WHEN (CAST(p.EFFECTIVE_DATE AS DATE) < CURDATE()) THEN 'Late' ELSE 'Upcoming' END) AS PaymentStatus,(CASE WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN 'Received' WHEN (CAST(p.EFFECTIVE_DATE AS DATE) >= CURDATE()) THEN 'Upcoming' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(CAST(p.EFFECTIVE_DATE AS DATE))) BETWEEN 1 AND 30) THEN 'Late (1-30 Days)' WHEN ((TO_DAYS(CURDATE()) - TO_DAYS(CAST(p.EFFECTIVE_DATE AS DATE))) BETWEEN 31 AND 90) THEN 'Late (31-90 Days)' ELSE 'Late (Over 90 Days)' END) AS OverdueBucket,(CASE WHEN ((p.STATUS_ID <> 'PMNT_RECEIVED') AND (CAST(p.EFFECTIVE_DATE AS DATE) < CURDATE())) THEN (TO_DAYS(CURDATE()) - TO_DAYS(CAST(p.EFFECTIVE_DATE AS DATE))) ELSE 0 END) AS DaysOverdue,CAST(p.EFFECTIVE_DATE AS DATE) AS DueDateKey,CAST(p.CREATED_STAMP AS DATE) AS CreatedDateKey,p.COMMENTS AS COMMENTS,p.CHEQUENUMBER AS ChequeNumber FROM (((((PAYMENT p LEFT JOIN PARTY pf ON((p.PARTY_ID_FROM = pf.PARTY_ID))) LEFT JOIN PAYMENT_TYPE pt_type ON((p.PAYMENT_TYPE_ID = pt_type.PAYMENT_TYPE_ID))) LEFT JOIN SALES_REQUEST sr ON((p.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) LEFT JOIN PRODUCT apt ON((sr.PRODUCT_ID = apt.PRODUCT_ID))) LEFT JOIN DimProjects proj ON((COALESCE(apt.PROJECT_ID,p.WORK_EFFORT_ID) = proj.ProjectId))) WHERE (p.STATUS_ID IS NULL OR p.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND (((p.PARTY_ID_TO = 'Company') AND (p.SALES_REQUEST_ID IS NOT NULL) AND (p.PAYMENT_TYPE_ID IN ('RECEIPT_ADVANCE_PAYMENT','RECEIPT_DUE_INSTALLMENT','RECEIPT_MAINTENANCE_AMOUNT')) AND (COALESCE(p.AMOUNT,0) > 0)));

-- fact_apartment_installment_payment_link: prepended to existing WHERE
CREATE OR REPLACE VIEW Fact_Apartment_Installment_Payment_Link AS SELECT i.SALES_REQUEST_ID AS SALES_REQUEST_ID,i.INSTALLMENT_NUMBER AS INSTALLMENT_NUMBER,i.DUE_DATE AS PlannedDueDate,CAST(i.DUE_DATE AS DATE) AS PlannedDueDateKey,i.AMOUNT AS PlannedAmount,i.IS_ADVANCE AS IS_ADVANCE,p.PAYMENT_ID AS PAYMENT_ID,p.STATUS_ID AS PaymentStatusId,p.EFFECTIVE_DATE AS ActualEffectiveDate,CAST(p.EFFECTIVE_DATE AS DATE) AS ActualDueDateKey,p.AMOUNT AS ActualAmount,(CASE WHEN (p.PAYMENT_ID IS NULL) THEN 'Missing Payment' WHEN (ABS((COALESCE(p.AMOUNT,0) - i.AMOUNT)) > 0.01) THEN 'Amount Mismatch' WHEN (CAST(p.EFFECTIVE_DATE AS DATE) <> CAST(i.DUE_DATE AS DATE)) THEN 'Date Mismatch' WHEN (p.STATUS_ID = 'PMNT_RECEIVED') THEN 'Paid' ELSE 'Matched - Not Paid' END) AS MatchStatus,(COALESCE(p.AMOUNT,0) - i.AMOUNT) AS AmountDifference,(TO_DAYS(CAST(p.EFFECTIVE_DATE AS DATE)) - TO_DAYS(CAST(i.DUE_DATE AS DATE))) AS DaysDifference,p.COMMENTS AS PaymentComments,p.PAYMENT_TYPE_ID AS PAYMENT_TYPE_ID,p.PARTY_ID_FROM AS CustomerPartyId,pf.DESCRIPTION AS CustomerName,p.CHEQUENUMBER AS ChequeNumber,p.CHEQUEDATE AS ChequeDate,sr.PRODUCT_ID AS ApartmentId,sr.STATUS_ID AS SalesRequestStatus FROM (((SALES_REQUEST_INSTALLMENT i LEFT JOIN PAYMENT p ON(((p.SALES_REQUEST_ID = i.SALES_REQUEST_ID) AND (CAST(p.EFFECTIVE_DATE AS DATE) = CAST(i.DUE_DATE AS DATE)) AND (ABS((COALESCE(p.AMOUNT,0) - i.AMOUNT)) <= 0.01) AND (p.PAYMENT_TYPE_ID IN ('RECEIPT_ADVANCE_PAYMENT','RECEIPT_DUE_INSTALLMENT','RECEIPT_MAINTENANCE_AMOUNT'))))) LEFT JOIN PARTY pf ON((p.PARTY_ID_FROM = pf.PARTY_ID))) LEFT JOIN SALES_REQUEST sr ON((i.SALES_REQUEST_ID = sr.SALES_REQUEST_ID))) WHERE (p.STATUS_ID IS NULL OR p.STATUS_ID NOT IN ('PMNT_VOID','PMNT_CANCELLED')) AND ((i.SALES_REQUEST_ID IS NOT NULL)) ORDER BY i.SALES_REQUEST_ID,i.INSTALLMENT_NUMBER,p.PAYMENT_ID;
